if(!exists('population_stability',mode='function'))library(creditratingsystem)
close<-function(a,b,tol=1e-12)stopifnot(max(abs(unlist(a)-unlist(b)))<tol)
d<-list(model_id='monitor',model_version='1',parameter_version='1',data_fingerprint='synthetic-populations',population_id='applicants',split_id='future',prediction_origin='EXTERNAL',evaluation_cutoff='2024-01-01',reference_as_of='2020-01-01',current_as_of='2021-01-01',target=list(event='default',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='performing'));bins<-list(binning_id='frozen',version='1',known_at='2019-01-01',kind='numeric',cutpoints=list(1),reference_support=list(0,2))
r<-population_stability(c(0,0,2,2),c(0,2,2,2),bins,c('psi','jsd','wasserstein'),0,d)$value;close(r$metrics$psi$value,.25*log(3));close(r$metrics$wasserstein$value,.5);close(r$metrics$jsd$value,.5*(.5*log(.5/.375)+.5*log(.5/.625)+.25*log(.25/.375)+.75*log(.75/.625)))
r<-population_stability(list(0,NULL),c(2,2),bins,c('psi','jsd','wasserstein'),0,d)$value;stopifnot(r$metrics$psi$status=='INFINITE',is.null(r$metrics$psi$value),r$coverage$missing_share_change==-.5);close(r$metrics$jsd$value,log(2));close(r$metrics$wasserstein$value,2)
bins$kind<-'categorical';bins$levels<-list('a','b');r<-population_stability(list('a',NULL,'new'),list('a',NULL,'new'),bins,c('psi','jsd'),.5,d)$value;stopifnot(r$metrics$psi$value==0,r$metrics$jsd$value==0,r$coverage$current_novel_count==1);r<-population_stability(list(),list('a'),bins,c('psi','jsd'),.5,d)$value;stopifnot(r$applicability=='NOT_APPLICABLE')
